// TROQUE o token (use o mesmo no CRM e no agente)
const TOKEN = 'TROQUE-ESTE-TOKEN';
// O agente só alimenta o CRM. Qualquer outro tipo é recusado.
const PERMITIDOS = ['contato', 'interacao', 'negocio', 'etapa', 'tarefa'];

const req = $input.first().json;
const b = req.body || {};
const token = (req.headers || {})['x-nucleo-token'] || (req.query || {}).token || b.token;
if (token !== TOKEN) throw new Error('Token inválido');

const lista = Array.isArray(b) ? b : Array.isArray(b.eventos) ? b.eventos : [b];
const saida = [];
for (const e of lista) {
  const tipo = String(e.tipo || '').toLowerCase();
  if (!PERMITIDOS.includes(tipo)) throw new Error(`Tipo "${tipo}" não permitido. Use: ${PERMITIDOS.join(', ')}`);
  saida.push({ json: {
    id: String(e.id || `${Date.now()}-${Math.random().toString(36).slice(2, 9)}`),
    tipo,
    dados: JSON.stringify(e.dados || {})
  } });
}
return saida;

// TROQUE o token (o mesmo informado no CRM, tela Agente WhatsApp)
const TOKEN = 'TROQUE-ESTE-TOKEN';
const q = $input.first().json.query || {};
if (q.token !== TOKEN) throw new Error('Token inválido');
return [{ json: { desde: Math.max(0, parseInt(q.desde, 10) || 0) } }];

const eventos = $input.all()
  .map(i => i.json)
  .filter(e => e.seq != null)
  .map(e => ({ ...e, seq: Number(e.seq) }));
return [{ json: { eventos } }];
